//! Replay of `tests/fixtures/agent-event-projector/oracle.json`, generated by
//! the real TS `mapAgentEvent` (see the fixture README).

use super::*;
use std::sync::Mutex;

const ORACLE: &str = include_str!("../../../tests/fixtures/agent-event-projector/oracle.json");
const PERCENT: &str = "/tmp/pdrs-agent-event-projector";

#[derive(Default)]
struct RecordingStore {
    calls: Mutex<Vec<JsValue>>,
}

impl GatewayToolResultArtifactStorePort for RecordingStore {
    fn persist(&self, input: &GatewayToolResultArtifactInput) -> Option<String> {
        let bytes = utf8_len(input.text.units());
        let returned = (bytes > DEFAULT_ARTIFACT_THRESHOLD_BYTES).then(|| {
            format!(
                "{}/{}/{}/{}.txt",
                PERCENT,
                safe_path_part(input.session_id.units()),
                safe_path_part(input.turn_id.units()),
                safe_path_part(input.tool_call_id.units()),
            )
        });
        let record = object([
            ("sessionId", JsValue::String(input.session_id.clone())),
            ("turnId", JsValue::String(input.turn_id.clone())),
            ("toolCallId", JsValue::String(input.tool_call_id.clone())),
            ("text", JsValue::String(input.text.clone())),
            ("bytes", number(bytes as f64)),
            (
                "returned",
                returned
                    .as_deref()
                    .map_or(JsValue::Undefined, JsValue::from),
            ),
        ]);
        self.calls.lock().unwrap().push(record);
        returned
    }
}

fn array(value: &JsValue) -> &[JsValue] {
    items(value)
}

fn stringified(value: &JsValue) -> String {
    pilotdeck_protocol::stringify_json(value)
        .expect("frame is JSON-serializable")
        .expect("frame is not undefined")
}

#[test]
fn agent_event_projections_match_ts_oracle() {
    let oracle = crate::test_baseline::oracle(ORACLE);
    let cases = array(field(&oracle, "cases"));
    assert_eq!(cases.len(), 94, "oracle case count");

    for case in cases {
        let name = field(case, "name")
            .as_string()
            .and_then(|value| value.to_utf8().ok())
            .expect("case name");
        let event = field(case, "event");
        let run_id = field(case, "runId")
            .as_string()
            .and_then(|value| value.to_utf8().ok())
            .expect("case runId");
        let forward = field(case, "forwardSubagentText")
            .as_bool()
            .expect("case forwardSubagentText");
        let store = Arc::new(RecordingStore::default());
        let options = GatewayAgentEventProjectorOptions {
            tool_result_artifacts: Some(store.clone()),
            forward_subagent_text: forward,
        };
        let actual = map_agent_event(event, &run_id, options);
        let expected = array(field(case, "frames"));
        assert_eq!(actual.len(), expected.len(), "case {name:?} frame count");
        for (index, (actual, expected)) in actual.iter().zip(expected).enumerate() {
            assert_eq!(
                stringified(actual),
                stringified(expected),
                "case {name:?} frame {index}"
            );
        }

        let expected_persist = array(field(case, "persist"));
        let recorded = store.calls.lock().unwrap();
        assert_eq!(
            recorded.len(),
            expected_persist.len(),
            "case {name:?} persist count"
        );
        for (index, (actual, expected)) in recorded.iter().zip(expected_persist).enumerate() {
            assert_eq!(
                stringified(actual),
                stringified(expected),
                "case {name:?} persist {index}"
            );
        }
    }
}

#[test]
fn unknown_and_missing_event_types_project_nothing() {
    for event in [
        object([("type", text("future_event"))]),
        object([("sessionId", text("s"))]),
        JsValue::Null,
        JsValue::String(JsString::from("turn_started")),
    ] {
        assert!(
            map_agent_event(
                &event,
                "run-1",
                GatewayAgentEventProjectorOptions::default()
            )
            .is_empty()
        );
    }
}

#[test]
fn default_store_only_persists_above_the_byte_threshold() {
    let root = std::env::temp_dir().join(format!("pdrs-projector-store-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    let store = GatewayToolResultArtifactStore::new(&root, 4);
    let short = GatewayToolResultArtifactInput {
        session_id: JsString::from("s"),
        turn_id: JsString::from("t"),
        tool_call_id: JsString::from("c"),
        text: JsString::from("abcd"),
    };
    assert_eq!(store.persist(&short), None);
    let long = GatewayToolResultArtifactInput {
        text: JsString::from("abcde"),
        ..short
    };
    let path = store.persist(&long).expect("persisted above threshold");
    assert_eq!(std::fs::read_to_string(&path).unwrap(), "abcde");
    assert!(std::path::Path::new(&path).starts_with(root.join("s").join("t")));
    let _ = std::fs::remove_dir_all(&root);
}

#[test]
#[ignore = "requires PDRS_BASELINE at the fixed commit"]
fn agent_event_projector_fixtures_regenerate_identically_from_ts() {
    crate::test_baseline::regenerates_identically("agent-event-projector");
}
